// src/lib/plattform/backend/eg.js
//
// Fassade des Moduls Energiegemeinschaften (ElWG §§ 65–72). EINE Schnittstelle für alle Arbeitspakete; jedes Paket
// implementiert seine Operationen in eigenen Dateien (Demo und Frappe mit identischen Signaturen):
//   WP1 Stamm      backend/demo/eg-stamm.js      · backend/frappe/eg-stamm.js      (Frappe: plattform/api/eg_stamm.py)
//   WP2 EDA        backend/demo/eg-eda.js        · backend/frappe/eg-eda.js        (plattform/api/eg_eda.py)
//   WP3 Energie    backend/demo/eg-energie.js    · backend/frappe/eg-energie.js    (plattform/api/eg_energie.py)
//   WP4 Abrechnung backend/demo/eg-abrechnung.js · backend/frappe/eg-abrechnung.js (plattform/api/eg_abrechnung.py)
//   WP5 Gründung   backend/demo/eg-gruendung.js  · backend/frappe/eg-gruendung.js  (plattform/api/eg_gruendung.py)
//   WP6 Portale    backend/demo/eg-portal.js     · backend/frappe/eg-portal.js     (plattform/api/eg_portal.py)
// Vertrag (Signaturen, Rückgaben, Rechte): docs/EG-SCHNITTSTELLEN.md und docs/API.md, Abschnitt „Energiegemeinschaften“.
// Datenmodell: src/lib/plattform/eg/modell.js. Diese Datei pflegt WP1; andere Pakete ändern nur ihre Zeile in EG_OPERATIONEN
// per Patch (docs/eg/<paket>.md).
//
// Auswahl wie backend(): Frappe bei PLATTFORM_BACKEND=frappe, sonst Demo (503 im Produktions-Build ohne PLATTFORM_DEMO=1).
// n = angemeldeter Nutzer (aus route()/portalNutzer), SYSTEM-Aufrufe (Scheduler, Ereignisse) mit egSystem().
// Nur serverseitig verwenden.

import * as demoStamm from "./demo/eg-stamm";
import * as demoEda from "./demo/eg-eda";
import * as demoEnergie from "./demo/eg-energie";
import * as demoAbrechnung from "./demo/eg-abrechnung";
import * as demoGruendung from "./demo/eg-gruendung";
import * as demoPortal from "./demo/eg-portal";
import * as frappeStamm from "./frappe/eg-stamm";
import * as frappeEda from "./frappe/eg-eda";
import * as frappeEnergie from "./frappe/eg-energie";
import * as frappeAbrechnung from "./frappe/eg-abrechnung";
import * as frappeGruendung from "./frappe/eg-gruendung";
import * as frappePortal from "./frappe/eg-portal";
import { backendName, KONFIG_FEHLER } from "./index";
import { PlattformFehler } from "../fehler";
import { EG_EREIGNISSE } from "../eg/modell";

/**
 * Operationen je Paket (Signaturen: docs/EG-SCHNITTSTELLEN.md, Abschnitt 4).
 *
 * WP1 Stamm (Lesen für alle Pakete, Schreiben Stammdaten):
 *   egKontext(n,{gemeinschaftId?}) → {gemeinschaften:[{id,name,modell,status,rollen[]}]}  Rollen des Kontos je Gemeinschaft
 *   egGemeinschaften(n,{status?,modell?,q?}) → {gemeinschaften[], kennzahlen, darfSchreiben}   Backoffice-Liste mit Kennzahlen
 *   egGemeinschaft(n,id) → {gemeinschaft, organe[], mitglieder[], zaehlpunkte[], teilnahmen[], anlagen[], tarife[], verteilschluessel[], netzbetreiber[], rollen[], rechte{}, hinweise[]}
 *   egGemeinschaftSpeichern(n,{id?,daten}) → gemeinschaft          egGemeinschaftStatus(n,id,{nach,grund?}) → gemeinschaft
 *   egOrganSpeichern(n,{gemeinschaftId,id?,daten}) → organ         egOrganBeenden(n,id,{bis}) → organ
 *   egMitgliedSpeichern(n,{gemeinschaftId,id?,daten}) → mitglied   egMitgliedStatus(n,id,{nach,grund?,zum?}) → mitglied
 *   egZaehlpunktSpeichern(n,{gemeinschaftId,id?,daten}) → zaehlpunkt
 *   egTeilnahmeSpeichern(n,{gemeinschaftId,id?,daten}) → teilnahme   (nur Entwurf bzw. TF-Wunsch; Status nur per Übergang)
 *   egTeilnahmeUebergang(n,teilnahmeId,{ereignis,datum?,consentId?,teilnahmefaktor?,responsecode?,prozessId?,grund?}) → teilnahme
 *   egAnlageSpeichern(n,{gemeinschaftId,id?,daten}) → anlage       egTarifSpeichern(n,{gemeinschaftId,id?,daten}) → tarif
 *   egVerteilschluesselSpeichern(n,{gemeinschaftId,id?,daten}) → verteilschluessel
 *   egMassenaktion(n,gemeinschaftId,{aktion,ids[],werte{}}) → {geaendert, fehler[]}
 *   egCsvImport(n,gemeinschaftId,{art,csv,ausfuehren}) → {vorschau[], fehler[], angelegt, geaendert}
 *   egCsvExport(n,gemeinschaftId,{art}) → {dateiname, csv}
 *   egNetzbetreiber(n) → {netzbetreiber[]}                         egNetzentgeltRegeln(n,{stichtag?}) → {regeln[]}
 *   egVerwaltung(n,gemeinschaftId) → Organe-Sicht (Vorstand/Kassier/Schriftführung/Rechnungsprüfung)
 *   egMigrationVorschau(n) · egMigrationAusfuehren(n) → {gemeinschaften, mitglieder, zaehlpunkte, teilnahmen, warnungen[]}
 * WP2 EDA:
 *   edaProzesse(n,gemeinschaftId,{status?,code?}) · edaProzess(n,id) · edaAnmelden(n,gemeinschaftId,{teilnahmeIds[],offline?})
 *   edaTfAendern(n,gemeinschaftId,{aenderungen:[{teilnahmeId,teilnahmefaktor,ab}]}) · edaAbmelden(n,gemeinschaftId,{teilnahmeIds[],zum})
 *   edaVerteilschluesselSenden(n,verteilschluesselId) · edaPodlistAnfordern(n,gemeinschaftId) · edaNachforderung(n,{zaehlpunktId,von,bis})
 *   edaNachrichtEingang(sys,{xml,quelle}) · edaFristenLauf(sys) · edaGemeinschaftBereit(sys,{gemeinschaftId})
 * WP3 Energie:
 *   enMessreihen(n,{gemeinschaftId,zaehlpunktId?,von,bis,groessen?}) · enEnergiedatenEmpfangen(sys,payload)
 *   enPeriodenwerte(n,gemeinschaftId,von,bis) → {zaehlpunkte:[{zaehlpunktId,teilnahmeId,groessen{groesse:kWh},vollstaendig,anteilL3}]}
 *   enQualitaet(n,gemeinschaftId,{monat}) · enAbweichungsbericht(n,gemeinschaftId,{monat}) · enCsvImport(n,gemeinschaftId,{csv})
 *   enSimulation(n,{daten}) · enSimulationen(n,{gemeinschaftId?}) · enPrognose(n,gemeinschaftId) · enOptimierung(n,{zaehlpunktId})
 * WP4 Abrechnung:
 *   abPerioden(n,gemeinschaftId) · abPeriodeAnlegen(n,gemeinschaftId,{von,bis,art}) · abPeriodeAktion(n,id,{aktion,…})
 *   abBelege(n,{gemeinschaftId?,mitgliedId?,periodeId?}) · abBelegPdf(n,id) · abZahlungslauf(n,gemeinschaftId,{art,belegIds[]})
 *   abCamtImport(n,gemeinschaftId,{xml}) · abMahnlauf(n,gemeinschaftId) · abBuchungen(n,gemeinschaftId,{jahr})
 *   abExport(n,gemeinschaftId,{art,jahr}) · abKleinunternehmer(n,gemeinschaftId) · abJahresbescheinigung(n,mitgliedId,{jahr})
 * WP5 Gründung:
 *   grAuftraege(n) · grAuftrag(n,id) · grAuftragAnlegen(n,{daten}) · grAuftragAktion(n,id,{aktion,…}) · grSchrittAktion(n,id,{schritt,aktion,…})
 *   grDokumentErzeugen(n,{gemeinschaftId,vorlage,daten}) · grImportVorschau(n,gemeinschaftId,{csv}) · grImportAusfuehren(n,importId)
 *   grFoerdercheck(n,{gemeinschaftId?,daten}) · grVersammlungen(n,gemeinschaftId) · grAufloesung(n,gemeinschaftId,{aktion})
 * WP6 Portale:
 *   ptUebersicht(n) · ptGemeinschaft(n,gemeinschaftId) · ptBeitrittAntrag(n,gemeinschaftId,{daten},{ip}) · ptKuendigung(n,mitgliedId,{zum})
 *   ptTfWunsch(n,teilnahmeId,{teilnahmefaktor}) · ptInteresse(null|n,{daten},{ip}) · ptGemeindeSicht(n) · ptDatenauskunft(n)
 *   ptRechner(null,{daten}) (öffentlich, ohne Personendaten) · ptBelege(n) · ptEnergie(n,{zaehlpunktId,von,bis})
 */
export const EG_OPERATIONEN = {
  stamm: [
    "egKontext", "egGemeinschaften", "egGemeinschaft", "egGemeinschaftSpeichern", "egGemeinschaftStatus", "egOrganSpeichern", "egOrganBeenden",
    "egMitgliedSpeichern", "egMitgliedStatus", "egZaehlpunktSpeichern", "egTeilnahmeSpeichern", "egTeilnahmeUebergang", "egAnlageSpeichern",
    "egTarifSpeichern", "egVerteilschluesselSpeichern", "egMassenaktion", "egCsvImport", "egCsvExport", "egNetzbetreiber", "egNetzentgeltRegeln",
    "egVerwaltung", "egMigrationVorschau", "egMigrationAusfuehren",
  ],
  eda: ["edaProzesse", "edaProzess", "edaAnmelden", "edaTfAendern", "edaAbmelden", "edaVerteilschluesselSenden", "edaPodlistAnfordern", "edaNachforderung", "edaNachrichtEingang", "edaFristenLauf", "edaGemeinschaftBereit"],
  energie: ["enMessreihen", "enEnergiedatenEmpfangen", "enPeriodenwerte", "enQualitaet", "enAbweichungsbericht", "enCsvImport", "enSimulation", "enSimulationen", "enPrognose", "enOptimierung"],
  abrechnung: ["abPerioden", "abPeriodeAnlegen", "abPeriodeAktion", "abBelege", "abBelegPdf", "abZahlungslauf", "abCamtImport", "abMahnlauf", "abBuchungen", "abExport", "abKleinunternehmer", "abJahresbescheinigung"],
  gruendung: ["grAuftraege", "grAuftrag", "grAuftragAnlegen", "grAuftragAktion", "grSchrittAktion", "grDokumentErzeugen", "grImportVorschau", "grImportAusfuehren", "grFoerdercheck", "grVersammlungen", "grAufloesung"],
  portal: ["ptUebersicht", "ptGemeinschaft", "ptBeitrittAntrag", "ptKuendigung", "ptTfWunsch", "ptInteresse", "ptGemeindeSicht", "ptDatenauskunft", "ptRechner", "ptBelege", "ptEnergie"],
};
export const EG_ALLE_OPERATIONEN = Object.values(EG_OPERATIONEN).flat();

const DEMO = { ...demoStamm, ...demoEda, ...demoEnergie, ...demoAbrechnung, ...demoGruendung, ...demoPortal };
const FRAPPE = { ...frappeStamm, ...frappeEda, ...frappeEnergie, ...frappeAbrechnung, ...frappeGruendung, ...frappePortal };

if (process.env.NODE_ENV !== "production") {
  for (const [name, impl] of [["demo", DEMO], ["frappe", FRAPPE]]) {
    const fehlt = EG_ALLE_OPERATIONEN.filter((op) => typeof impl[op] !== "function");
    if (fehlt.length) console.warn(`[plattform] Energiegemeinschaften ${name}: fehlende Operationen ${fehlt.join(", ")}`);
  }
}

/** Aktive Implementierung (alle Pakete) oder 503 */
export function egBackend() {
  const n = backendName();
  if (n === "frappe") return FRAPPE;
  if (n === "demo") return DEMO;
  throw new PlattformFehler(503, KONFIG_FEHLER);
}

/** Systemkonto für Scheduler und Ereignisse (wirkt wie Backoffice-Leitung; Operationen protokollieren „System“) */
export const egSystem = () => ({ id: "system-eg", rollen: ["admin"], backofficeRollen: ["leitung"], system: true });

/**
 * Ereignis an das zuständige Paket weiterreichen (modell.js EG_EREIGNISSE). Ohne Empfänger-Operation (nur Information)
 * → { zugestellt: false }. Fehler des Empfängers werden NICHT verschluckt (Absender entscheidet über Wiederholung).
 */
export async function egEreignisSenden(name, payload = {}) {
  const e = EG_EREIGNISSE[name];
  if (!e) throw new PlattformFehler(422, `Unbekanntes Ereignis „${name}“.`);
  if (!e.operation) return { zugestellt: false };
  const b = egBackend();
  return { zugestellt: true, ergebnis: await b[e.operation](egSystem(), payload) };
}
// src/lib/plattform/backend/demo/eg-energie.js
//
// STUB WP3 „Energiedaten, Verteilung, Simulation und Prognose“ (Demo-Backend) – angelegt von WP1 als Platzhalter, damit die Fassade
// backend/eg.js vollständig ist. WP3 ersetzt diese Datei vollständig durch die echte Implementierung (gleiche Exporte,
// Signaturen laut docs/EG-SCHNITTSTELLEN.md, Abschnitt 4). Bis dahin antwortet jede Operation mit 501.

import { PlattformFehler } from "../../fehler";

const offen = (op) => async () => {
  throw new PlattformFehler(501, `Energiegemeinschaften: „${op}“ ist noch nicht umgesetzt (WP3).`);
};

export const enMessreihen = offen("enMessreihen");
export const enEnergiedatenEmpfangen = offen("enEnergiedatenEmpfangen");
export const enPeriodenwerte = offen("enPeriodenwerte");
export const enQualitaet = offen("enQualitaet");
export const enAbweichungsbericht = offen("enAbweichungsbericht");
export const enCsvImport = offen("enCsvImport");
export const enSimulation = offen("enSimulation");
export const enSimulationen = offen("enSimulationen");
export const enPrognose = offen("enPrognose");
export const enOptimierung = offen("enOptimierung");
// src/lib/plattform/backend/frappe/eg-energie.js
//
// STUB WP3 „Energiedaten, Verteilung, Simulation und Prognose“ (Frappe-Adapter) – angelegt von WP1 als Platzhalter, damit die Fassade
// backend/eg.js vollständig ist. WP3 ersetzt diese Datei vollständig durch die echte Implementierung (gleiche Exporte,
// Signaturen laut docs/EG-SCHNITTSTELLEN.md, Abschnitt 4). Bis dahin antwortet jede Operation mit 501.
// Vorgesehene Frappe-Methoden (oekoinvest_app.plattform.api.eg_energie): enMessreihen → eg_energie.messreihen, enEnergiedatenEmpfangen → eg_energie.energiedaten_empfangen, enPeriodenwerte → eg_energie.periodenwerte, enQualitaet → eg_energie.qualitaet, enAbweichungsbericht → eg_energie.abweichungsbericht, enCsvImport → eg_energie.csv_import, enSimulation → eg_energie.simulation, enSimulationen → eg_energie.simulationen, enPrognose → eg_energie.prognose, enOptimierung → eg_energie.optimierung.
// Muster: backend/frappe/eg-stamm.js (Object.assign(METHODEN, …) + aufruf).

import { PlattformFehler } from "../../fehler";

const offen = (op) => async () => {
  throw new PlattformFehler(501, `Energiegemeinschaften: „${op}“ ist im Frappe-Backend noch nicht umgesetzt (WP3).`);
};

export const enMessreihen = offen("enMessreihen");
export const enEnergiedatenEmpfangen = offen("enEnergiedatenEmpfangen");
export const enPeriodenwerte = offen("enPeriodenwerte");
export const enQualitaet = offen("enQualitaet");
export const enAbweichungsbericht = offen("enAbweichungsbericht");
export const enCsvImport = offen("enCsvImport");
export const enSimulation = offen("enSimulation");
export const enSimulationen = offen("enSimulationen");
export const enPrognose = offen("enPrognose");
export const enOptimierung = offen("enOptimierung");
// src/lib/plattform/backend/frappe/eg-stamm.js
//
// Frappe-Adapter WP1 „Kern-Stammdaten“ des Moduls Energiegemeinschaften. Methoden in oekoinvest_app.plattform.api.eg_stamm –
// Signaturen identisch zu backend/demo/eg-stamm.js (Vertrag: docs/EG-SCHNITTSTELLEN.md). Frappe prüft Rolle, Kontext-Rolle
// je Gemeinschaft (eg_stamm_kern.rollen_von) und Bereich „eg“ der Rechte-Matrix selbst.

import { METHODEN, frappeAufruf as aufruf } from "../frappe";

Object.assign(METHODEN, {
  egKontext: "eg_stamm.kontext",
  egGemeinschaften: "eg_stamm.gemeinschaften",
  egGemeinschaft: "eg_stamm.gemeinschaft",
  egGemeinschaftSpeichern: "eg_stamm.gemeinschaft_speichern",
  egGemeinschaftStatus: "eg_stamm.gemeinschaft_status",
  egOrganSpeichern: "eg_stamm.organ_speichern",
  egOrganBeenden: "eg_stamm.organ_beenden",
  egMitgliedSpeichern: "eg_stamm.mitglied_speichern",
  egMitgliedStatus: "eg_stamm.mitglied_status",
  egZaehlpunktSpeichern: "eg_stamm.zaehlpunkt_speichern",
  egTeilnahmeSpeichern: "eg_stamm.teilnahme_speichern",
  egTeilnahmeUebergang: "eg_stamm.teilnahme_uebergang",
  egAnlageSpeichern: "eg_stamm.anlage_speichern",
  egTarifSpeichern: "eg_stamm.tarif_speichern",
  egVerteilschluesselSpeichern: "eg_stamm.verteilschluessel_speichern",
  egMassenaktion: "eg_stamm.massenaktion",
  egCsvImport: "eg_stamm.csv_import",
  egCsvExport: "eg_stamm.csv_export",
  egNetzbetreiber: "eg_stamm.netzbetreiber",
  egNetzentgeltRegeln: "eg_stamm.netzentgelt_regeln",
  egVerwaltung: "eg_stamm.verwaltung",
  egMigrationVorschau: "eg_stamm.migration_vorschau",
  egMigrationAusfuehren: "eg_stamm.migration_ausfuehren",
});

export const egKontext = (n, { gemeinschaftId = "" } = {}) => aufruf("egKontext", { gemeinschaftId }, n);
export const egGemeinschaften = (n, filter = {}) => aufruf("egGemeinschaften", { filter }, n);
export const egGemeinschaft = (n, id) => aufruf("egGemeinschaft", { id }, n);
export const egGemeinschaftSpeichern = (n, { id = null, daten = {} } = {}) => aufruf("egGemeinschaftSpeichern", { id, daten }, n);
export const egGemeinschaftStatus = (n, id, daten = {}) => aufruf("egGemeinschaftStatus", { id, daten }, n);
export const egOrganSpeichern = (n, { gemeinschaftId = "", id = null, daten = {} } = {}) => aufruf("egOrganSpeichern", { gemeinschaftId, id, daten }, n);
export const egOrganBeenden = (n, id, daten = {}) => aufruf("egOrganBeenden", { id, daten }, n);
export const egMitgliedSpeichern = (n, { gemeinschaftId = "", id = null, daten = {} } = {}) => aufruf("egMitgliedSpeichern", { gemeinschaftId, id, daten }, n);
export const egMitgliedStatus = (n, id, daten = {}) => aufruf("egMitgliedStatus", { id, daten }, n);
export const egZaehlpunktSpeichern = (n, { gemeinschaftId = "", id = null, daten = {} } = {}) => aufruf("egZaehlpunktSpeichern", { gemeinschaftId, id, daten }, n);
export const egTeilnahmeSpeichern = (n, { gemeinschaftId = "", id = null, daten = {} } = {}) => aufruf("egTeilnahmeSpeichern", { gemeinschaftId, id, daten }, n);
export const egTeilnahmeUebergang = (n, teilnahmeId, daten = {}) => aufruf("egTeilnahmeUebergang", { teilnahmeId, daten }, n);
export const egAnlageSpeichern = (n, { gemeinschaftId = "", id = null, daten = {} } = {}) => aufruf("egAnlageSpeichern", { gemeinschaftId, id, daten }, n);
export const egTarifSpeichern = (n, { gemeinschaftId = "", id = null, daten = {} } = {}) => aufruf("egTarifSpeichern", { gemeinschaftId, id, daten }, n);
export const egVerteilschluesselSpeichern = (n, { gemeinschaftId = "", id = null, daten = {} } = {}) => aufruf("egVerteilschluesselSpeichern", { gemeinschaftId, id, daten }, n);
export const egMassenaktion = (n, gemeinschaftId, daten = {}) => aufruf("egMassenaktion", { gemeinschaftId, daten }, n);
export const egCsvImport = (n, gemeinschaftId, daten = {}) => aufruf("egCsvImport", { gemeinschaftId, daten }, n);
export const egCsvExport = (n, gemeinschaftId, { art = "" } = {}) => aufruf("egCsvExport", { gemeinschaftId, art }, n);
export const egNetzbetreiber = (n) => aufruf("egNetzbetreiber", {}, n);
export const egNetzentgeltRegeln = (n, { stichtag = "" } = {}) => aufruf("egNetzentgeltRegeln", { stichtag }, n);
export const egVerwaltung = (n, gemeinschaftId) => aufruf("egVerwaltung", { gemeinschaftId }, n);
export const egMigrationVorschau = (n) => aufruf("egMigrationVorschau", {}, n);
export const egMigrationAusfuehren = (n) => aufruf("egMigrationAusfuehren", {}, n);

// src/lib/plattform/eg/rechte.js
//
// Rechte je Gemeinschaft (Kontext-Rollen, Fachkonzept Abschnitt 5) – reine Funktionen, client- und serverseitig.
// Eigentümer: WP1. Python-Spiegel: plattform/eg_stamm_kern.py (EG_RECHTE, rollen_von, stufe_von) – Abgleich im Test.
//
// Zwei Ebenen:
//  1. Backoffice (Rolle admin): Bereich „eg“ der Rechte-Matrix (src/lib/plattform/rechte.js; Unterrolle „eg“ =
//     Betriebsführung Energiegemeinschaften). Daraus entstehen die Kontext-Rollen „organisator“ (Gemeinschaft mit aktivem
//     Dienstleistungs-/AV-Vertrag) bzw. „gruendung“ (Gemeinschaft vor dem Status „aktiv“). Ohne Schreibrecht im Bereich „eg“
//     wirken sie höchstens lesend.
//  2. Portal: Organ-Einträge (vorstand, kassier, schriftfuehrer, rechnungspruefer – Teamrollen innerhalb der Gemeinschaft,
//     analog Bank-Team) und Mitglied-Einträge mit Bezug zum Konto (mitglied, gemeinde, interessent). Das globale Konto kann
//     jede Portal-Rolle haben (mitglied, landwirt, unternehmen, kommune …) – maßgeblich ist der Eintrag in der Gemeinschaft.
//
// Stufen: 0 kein Zugriff, 1 lesen bzw. vorbereiten/vorschlagen, 2 ausführen/schreiben.

import { darfLesen, darfSchreiben } from "../rechte.js";
import { EG_TEAMROLLEN, GEMEINSCHAFT_STATUS, MITGLIED_AKTIV, ORGAN_FUNKTIONEN } from "./modell.js";

const R = Object.keys(EG_TEAMROLLEN); // interessent, mitglied, gemeinde, vorstand, kassier, schriftfuehrer, rechnungspruefer, organisator, gruendung

/**
 * Rechte-Matrix je Gemeinschaft. Spalten in der Reihenfolge von EG_TEAMROLLEN:
 * interessent, mitglied, gemeinde, vorstand, kassier, schriftfuehrer, rechnungspruefer, organisator, gruendung
 */
const M = {
  eigene_daten: { label: "Eigene Daten, Zählpunkte, Belege, Dashboard", s: [1, 2, 2, 2, 2, 2, 2, 0, 0] },
  beitritt: { label: "Beitritt beantragen, TF-Wunsch, Kündigung", s: [2, 2, 2, 0, 0, 0, 0, 0, 0] },
  mitgliederliste: { label: "Mitgliederliste (Name, Status)", s: [0, 0, 0, 2, 2, 2, 1, 2, 1] },
  mitglied_aufnehmen: { label: "Mitglied aufnehmen bzw. ablehnen (1 = vorbereiten)", s: [0, 0, 0, 2, 0, 0, 0, 1, 0] },
  stammdaten: { label: "Zählpunkte, Anlagen, Mitgliederdaten pflegen", s: [0, 0, 0, 2, 1, 2, 1, 2, 2] },
