  return schaetzCache.get(k);
}
/** Gemeinschaft ohne Messdaten (z. B. in Gründung): Verbrauch der Mitglieder nach Standardlastprofil, Erzeugung der Anlagen */
function schaetzGemeinschaft(db, g, tag, ohneZp) {
  const { j, d } = doy(tag);
  const v = new Array(96).fill(0);
  const e = new Array(96).fill(0);
  const ART = { privat: ["H0", 3500], landwirt: ["L0", 12000], kmu: ["G0", 30000], grossunternehmen: ["G0", 1500000], gemeinde: ["G1", 30000], oeffentlich: ["G1", 30000], verein: ["G0", 8000] };
  for (const m of E(db).mitglieder.filter((x) => x.gemeinschaftId === g.id && !["abgelehnt", "ausgeschieden", "ausgeschlossen"].includes(x.status))) {
    const [p, kwh] = ART[m.art] || ART.privat;
    const prof = jahresProfil(p, j);
    for (let q = 0; q < 96; q++) v[q] += prof[d * 96 + q] * kwh;
  }
  for (const a of E(db).anlagen.filter((x) => x.gemeinschaftId === g.id && x.art === "pv" && x.status !== "stillgelegt")) {
    const zp = E(db).zaehlpunkte.find((x) => x.anlageId === a.id);
    if (zp?.id === ohneZp) continue;
    const pv = jahresProfilPv(j, a);
    for (let q = 0; q < 96; q++) e[q] += pv[d * 96 + q] * (a.kwp || 0);
  }
  return { e, v };
}

// ================================================================ Übersicht für Seiten (intern, kein Teil des Vertrags)

/** Dashboard-Daten (Seite /portal/admin/eg/[id]/energiedaten und Organ-Reiter): 13 Monate, letzte 7 Tage, Kennzahlen */
export async function enDashboardIntern(n, gemeinschaftId) {
  const monate = await enMessreihen(n, { gemeinschaftId, von: `${monatPlus(monatVon(heute()), -12)}-01`, bis: plusTag(heute(), -1), aufloesung: "monat" });
  const tage = await enMessreihen(n, { gemeinschaftId, von: plusTag(heute(), -30), bis: plusTag(heute(), -1), aufloesung: "tag" });
  const woche = await enMessreihen(n, { gemeinschaftId, von: plusTag(heute(), -7), bis: plusTag(heute(), -1) });
  return { monate: monate.zeilen, tage: tage.zeilen, woche: woche.tage, heute: heute() };
}

